P = "paper"
def E(*qs): return [{"source": P, "quote": q} for q in qs]
def C(id, name, gloss, requires, evidence, aliases=(), known=False, title=None, symbols=None):
    d = {"id": id, "name": name, "aliases": list(aliases), "gloss": gloss,
         "requires": list(requires), "known": known, "evidence": evidence}
    if title: d["title"] = title
    if symbols: d["symbols"] = [{"symbol": s, "name": n, "meaning": m, "relation": r} for s, n, m, r in symbols]
    return d

