ans = {"target": "main-theorem", "concepts": cs}
# checks
ids = {c["id"] for c in cs}
src = open(sys.argv[1]).read()
norm = lambda s: re.sub(r"\s+", "", s)
ns = norm(src)
for c in cs:
    for r in c["requires"]:
        assert r in ids, (c["id"], r)
    for e in c["evidence"]:
        if norm(e["quote"]) not in ns: print("MISSING", c["id"], e["quote"][:60])
json.dump(ans, open(sys.argv[2], "w"), indent=1, ensure_ascii=False)
print(len(cs))
